//! Runs Comark's own SPEC examples (`tests/fixtures/comark-spec.json`,
//! generated by `scripts/extract_comark_spec.py`).

use oxmark::{to_html_with, HtmlOptions, Options};

/// Comark indents its HTML, puts inline elements on lines of their own and
/// writes void tags without a slash. Whitespace next to a tag is dropped on
/// both sides before comparing, and so are line indents.
fn normalize(html: &str) -> String {
    let html = html
        .lines()
        .map(str::trim)
        .collect::<Vec<_>>()
        .join("\n")
        .replace(" />", ">");
    let mut out = String::with_capacity(html.len());
    let mut rest = html.as_str();
    while let Some(open) = rest.find('<') {
        let close = rest[open..].find('>').map_or(rest.len(), |i| open + i + 1);
        out.push_str(rest[..open].trim_end());
        out.push_str(&rest[open..close]);
        rest = rest[close..].trim_start();
    }
    out.push_str(rest);
    out
}

/// Cases that oxmark renders differently on purpose.
fn known_difference(name: &str) -> bool {
    // Comark writes `\&amp;` as `&amp;`, which reads back as `&`. oxmark
    // escapes the `&` so the text shows `&amp;` as written.
    name == "common-mark/paragraph-escaped-entity"
}

/// The options of a case, or `None` when it needs a Comark plugin that
/// oxmark does not have (syntax highlighting, emoji, bindings).
fn options(v: &serde_json::Value) -> Option<(Options, HtmlOptions<'static>)> {
    let mut options = Options::default();
    let mut html = HtmlOptions::default();
    for (key, value) in v.as_object().unwrap() {
        match (key.as_str(), value) {
            ("autoUnwrap", v) => html.unwrap = v.as_bool().unwrap(),
            ("headingIds", serde_json::Value::Bool(b)) => options.heading_ids = *b,
            ("headingIds", v) => options.nested_heading_ids = v == "nested",
            ("highlight", v) if v.is_null() || *v == false => {}
            ("maxInlineAttributes" | "blockAttributesStyle", _) => {}
            _ => return None,
        }
    }
    Some((options, html))
}

#[test]
fn comark_spec_html() {
    let value: serde_json::Value =
        serde_json::from_str(include_str!("fixtures/comark-spec.json")).unwrap();
    let filter = std::env::var("SPEC").unwrap_or_default();
    let mut passed = Vec::new();
    let mut failed = Vec::new();
    for case in value.as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        if !name.contains(&filter) {
            continue;
        }
        let Some((options, html)) = options(&case["options"]) else {
            continue;
        };
        let markdown = case["markdown"].as_str().unwrap();
        let expected = case["html"].as_str().unwrap();
        let actual = to_html_with(markdown, &options, &html);
        if normalize(&actual) == normalize(expected) {
            passed.push(name);
        } else {
            failed.push(format!(
                "{name}\n--- input\n{markdown}\n--- expected\n{expected}\n--- actual\n{actual}"
            ));
        }
    }
    if std::env::var("VERBOSE").is_ok() {
        eprintln!("{}", failed.join("\n\n"));
    }
    eprintln!("passed {} / {}", passed.len(), passed.len() + failed.len());
    let unexpected: Vec<&String> = failed
        .iter()
        .filter(|f| !known_difference(f.lines().next().unwrap()))
        .collect();
    assert!(
        unexpected.is_empty(),
        "{}",
        unexpected
            .iter()
            .map(|f| f.as_str())
            .collect::<Vec<_>>()
            .join("\n\n")
    );
}
